<?php
require_once 'config.php'; require_once 'includes/security.php'; require_once 'includes/email_helper.php';
$message=''; $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') { try { require_csrf(); $email=trim($_POST['email']??''); if(!filter_var($email,FILTER_VALIDATE_EMAIL)) throw new RuntimeException('Enter a valid email address.'); $stmt=$conn->prepare('SELECT id,full_name,email FROM users WHERE email=? AND is_active=1 LIMIT 1'); $stmt->bind_param('s',$email); $stmt->execute(); $user=$stmt->get_result()->fetch_assoc(); $stmt->close(); if($user){ $token=bin2hex(random_bytes(32)); $hash=hash('sha256',$token); $expires=date('Y-m-d H:i:s',time()+3600); $stmt=$conn->prepare('INSERT INTO password_resets (user_id,token_hash,expires_at) VALUES (?,?,?)'); $stmt->bind_param('iss',$user['id'],$hash,$expires); $stmt->execute(); $stmt->close(); $link=(($_SERVER['HTTPS']??'off')==='on'?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').rtrim(dirname($_SERVER['PHP_SELF']),'/').'/reset_password.php?token='.urlencode($token); $body="Hello {$user['full_name']},\n\nUse this link within one hour to reset your password:\n$link\n\nIf you did not request this, ignore the message."; send_email_notification($conn,(int)$user['id'],null,$user['email'],'Password reset request',$body); audit_log($conn,'request_password_reset','user',(int)$user['id'],'Password reset requested'); $message='If that email exists, a reset link has been generated. In this college demo, check logs/emails.log for the link.'; } else { $message='If that email exists, a reset link has been generated.'; } } catch(Throwable $e){$error='Unable to create a reset request. Please try again.';} }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Forgot Password | Grievance Portal</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="card border-0 shadow-sm mx-auto" style="max-width:520px"><div class="card-body p-4"><h3>Forgot password</h3><p class="text-muted">Enter your account email to generate a one-hour reset link.</p><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="mb-3"><label class="form-label">Email</label><input class="form-control" type="email" name="email" required></div><button class="btn btn-primary w-100">Generate reset link</button></form><a class="d-block text-center mt-3" href="login.php">Back to login</a></div></div></main></body></html>
